function defaultState(){return {version:1,schemaVersion:6,attempts:[],completed:{},proficiency:{},diagnostics:{},reflections:{},drafts:{workshop:{},reflections:{},investigations:{},constructions:{},pilot:{}},observationEvidence:{},constructionEvidence:{},constructionHistory:[],freeConstructions:[],humanReviews:[],pilotStudies:[],investigations:{},activeInvestigation:null,customCourses:[],artifacts:[],visitors:[],resources:[],activeLesson:null,activeQuiz:null,lastSession:null,lastView:'overview',prefs:{theme:'light',depth:'deep',alias:'Learner',focus:null,lessonMode:'guided',investigationMode:'short',languageSupport:true},activity:[],createdAt:new Date().toISOString()};}
function readState(){try{let x=JSON.parse(STORE.getItem(STORAGE_KEY));if(!x||x.version!==1)return defaultState();const d=defaultState();return {...d,...x,artifacts:Array.isArray(x.artifacts)?x.artifacts:[],visitors:Array.isArray(x.visitors)?x.visitors:[],resources:Array.isArray(x.resources)?x.resources:[],constructionHistory:Array.isArray(x.constructionHistory)?x.constructionHistory:[],freeConstructions:Array.isArray(x.freeConstructions)?x.freeConstructions:[],humanReviews:Array.isArray(x.humanReviews)?x.humanReviews:[],pilotStudies:Array.isArray(x.pilotStudies)?x.pilotStudies:[],observationEvidence:x.observationEvidence&&typeof x.observationEvidence==='object'&&!Array.isArray(x.observationEvidence)?x.observationEvidence:{},proficiency:x.proficiency&&typeof x.proficiency==='object'&&!Array.isArray(x.proficiency)?x.proficiency:{},investigations:x.investigations&&typeof x.investigations==='object'&&!Array.isArray(x.investigations)?x.investigations:{},activeInvestigation:x.activeInvestigation&&typeof x.activeInvestigation==='object'?x.activeInvestigation:null,drafts:{workshop:x.drafts?.workshop&&typeof x.drafts.workshop==='object'?x.drafts.workshop:{},reflections:x.drafts?.reflections&&typeof x.drafts.reflections==='object'?x.drafts.reflections:{},investigations:x.drafts?.investigations&&typeof x.drafts.investigations==='object'?x.drafts.investigations:{},constructions:x.drafts?.constructions&&typeof x.drafts.constructions==='object'?x.drafts.constructions:{},pilot:x.drafts?.pilot&&typeof x.drafts.pilot==='object'?x.drafts.pilot:{}},prefs:{...d.prefs,...x.prefs}};}catch(_){return defaultState();}}
let db=readState();
// Old v2 flags meant one successful item, not mastery. Migrate to honest first-transfer evidence.
if(!db.schemaVersion||db.schemaVersion<3){Object.entries(db.completed||{}).forEach(([id,done])=>{if(done&&!db.proficiency[id])db.proficiency[id]={status:'transfer',firstTransferAt:new Date().toISOString(),assisted:true,legacy:true};});db.completed={};db.schemaVersion=3;}migrateV4();migrateV5();migrateV6();
const restoredLesson=db.activeLesson;
let view=['overview','courses','course','lesson','quiz','results','patterns','insights','pilot','settings','workshop','artifact','shelf','commons','investigate'].includes(db.lastView)?db.lastView:'overview',courseId=restoredLesson?.courseId||db.activeQuiz?.courseId||'syntax',skillId=restoredLesson?.skillId||db.activeQuiz?.skillId||'constituents',lessonStep=restoredLesson?.step||0,lessonReveal=!!restoredLesson?.reveal,lessonSelected=restoredLesson?.selected??null,lessonFeedback=restoredLesson?.feedback||null,lessonHint=!!restoredLesson?.hint,lessonHintUsed=!!restoredLesson?.hintUsed,attachmentMode=restoredLesson?.attachmentMode||'low',lessonBuild=restoredLesson?.build||freshBuild(),lessonProbe=restoredLesson?.probe||{stable:null,changed:null,other:null},lessonProbeReview=restoredLesson?.probeReview||{required:false,confirmed:!!restoredLesson?.reveal,initial:null},lessonTrial=restoredLesson?.trial||0,lessonPassed=!!restoredLesson?.passed,lessonAnswerIndex=(restoredLesson?.answerIndex??0)>1?Math.max(0,(restoredLesson?.answerIndex??2)-2):(restoredLesson?.answerIndex??0),session=db.activeQuiz||null,lastSession=db.lastSession||null,patternFilter='all',patternSearch='',editArtifactId=null,preparedPattern=null,preparedBody='',selectedCapsuleId=null,selectedArtifactId=null,reasoningReview=null;
if(view==='quiz'&&!session)view='overview';if(view==='lesson'&&!restoredLesson)view='overview';if(view==='artifact')view='workshop';if(view==='investigate'&&!db.activeInvestigation)view='overview';if(view==='investigate'){courseId=db.activeInvestigation.courseId;skillId=db.activeInvestigation.skillId;}

// v4: two delayed multiple-choice answers are retrieval evidence. Mastery also needs a completed reasoning investigation.
function migrateV4(){if(!db.constructionEvidence||typeof db.constructionEvidence!=='object'||Array.isArray(db.constructionEvidence))db.constructionEvidence={};if(!db.investigations||typeof db.investigations!=='object')db.investigations={};if(db.schemaVersion>=4)return;Object.entries(db.proficiency||{}).forEach(([id,p])=>{if(p&&p.status==='mastered'){p.retrievedAt=p.retrievedAt||p.masteredAt||new Date().toISOString();if(!db.investigations[id]?.completedAt){p.status='retrieved';p.masteredAt=null;p.migratedFromMastery=true;db.completed[id]=false;}}});db.schemaVersion=4;}
function migrateV5(){if(!Array.isArray(db.constructionHistory))db.constructionHistory=[];if(!Array.isArray(db.freeConstructions))db.freeConstructions=[];if(!db.drafts||typeof db.drafts!=='object')db.drafts={workshop:{},reflections:{},investigations:{},constructions:{}};if(!db.drafts.constructions||typeof db.drafts.constructions!=='object')db.drafts.constructions={};if(db.schemaVersion<5)db.schemaVersion=5;}
function migrateV6(){if(!Array.isArray(db.humanReviews))db.humanReviews=[];if(!Array.isArray(db.pilotStudies))db.pilotStudies=[];if(!db.drafts.pilot||typeof db.drafts.pilot!=='object')db.drafts.pilot={};db.prefs=db.prefs&&typeof db.prefs==='object'?db.prefs:{};if(!['guided','standard','review'].includes(db.prefs.lessonMode))db.prefs.lessonMode='guided';if(!['short','extended'].includes(db.prefs.investigationMode))db.prefs.investigationMode='short';if(typeof db.prefs.languageSupport!=='boolean')db.prefs.languageSupport=true;if(db.schemaVersion<6)db.schemaVersion=6;}
function allCourses(){return [...C.courses,...(db.customCourses||[])];}
function course(id){return allCourses().find(x=>x.id===id)||allCourses()[0];}
function skill(cid,sid){return course(cid).skills.find(x=>x.id===sid)||course(cid).skills[0];}
function key(cid,sid){return `${cid}/${sid}`;}
function save(){try{STORE.setItem(STORAGE_KEY,JSON.stringify(db));}catch(_){toast('Storage is unavailable here. Use Export Progress to save your work.');}}
function activity(type,title,description){db.activity.unshift({id:Date.now()+'-'+Math.random().toString(16).slice(2),type,title,description,at:new Date().toISOString()});db.activity=db.activity.slice(0,150);save();}
function record(cid,sid,isCorrect,kind,hinted=false){const now=new Date().toISOString();db.attempts.push({courseId:cid,skillId:sid,correct:!!isCorrect,kind,at:now,hinted:!!hinted});db.attempts=db.attempts.slice(-3000);const id=key(cid,sid),p=db.proficiency[id];if((p?.status==='mastered'||p?.status==='retrieved')&&!isCorrect&&kind!=='diagnostic'){p.status='review';p.reviewAt=now;p.reviewReason='Later performance contradicted earlier mastery.';db.completed[id]=false;activity('A pattern needs revisiting',skill(cid,sid).title,'New evidence has reopened this question.');}save();}
function attemptsFor(cid,sid){return db.attempts.filter(a=>(!cid||a.courseId===cid)&&(!sid||a.skillId===sid));}
function accuracy(cid,sid){let xs=attemptsFor(cid,sid);return xs.length?xs.filter(a=>a.correct).length/xs.length:null;}
const DAY_MS=24*60*60*1000,REVIEW_MS=14*DAY_MS;
function isMastered(cid,sid){const p=db.proficiency[key(cid,sid)];return !!(p&&p.status==='mastered'&&p.masteredAt&&(Date.now()-Date.parse(p.masteredAt))<=REVIEW_MS);}
function statusOf(cid,sid){const p=db.proficiency[key(cid,sid)];if(!p)return 'not-started';if(p.status==='mastered')return isMastered(cid,sid)?'mastered':'review';return p.status;}
function evidenceLabel(cid,sid){const st=statusOf(cid,sid);return st==='mastered'?'EVIDENCE SET COMPLETE':st==='retrieved'?'DELAYED RETRIEVAL SUCCESSFUL':st==='transfer'?'FIRST TRANSFER RECORDED':st==='review'?'NEW REVIEW EVIDENCE NEEDED':'START';}
function latestHumanReview(cid,sid){return (db.humanReviews||[]).filter(x=>x.courseId===cid&&x.skillId===sid).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0]||null;}
function evidenceProfile(cid,sid,compact=false){const id=key(cid,sid),p=db.proficiency[id],built=db.constructionEvidence[id],inv=investigation(cid,sid),review=latestHumanReview(cid,sid);const rows=[['Guided construction',built?'Completed':'Not yet completed'],['First transfer',p?.firstTransferAt?'Successful':'Not yet recorded'],['Delayed retrieval',p?.retrievedAt?'Successful':'Not yet successful'],['Investigation',inv?'Completed · written reasoning not assessed':'Not yet completed'],['Teacher or peer review',review?`${review.role} review recorded by ${review.reviewer}`:'Not recorded']];return `<div class="evidence-profile ${compact?'is-compact':''}">${rows.map(([label,value],i)=>`<div class="evidence-line ${!value.startsWith('Not')?'has-evidence':''}"><span>${i+1}</span><div><strong>${safe(label)}</strong><small>${safe(value)}</small></div></div>`).join('')}</div>`;}
function investigation(cid,sid){const r=db.investigations[key(cid,sid)];return r&&r.completedAt?r:null;}
function supportsMastery(cid,sid,retrievedAt){const inv=investigation(cid,sid);if(!inv||!retrievedAt)return false;if(inv.challengeFirstCorrect!==false)return true;return Date.parse(retrievedAt)>Date.parse(inv.completedAt);}
function retestDue(cid,sid){const questions=skill(cid,sid).retest;if(!Array.isArray(questions)||questions.length<2)return false;const p=db.proficiency[key(cid,sid)];if(!p)return false;if(p.status==='mastered')return !isMastered(cid,sid);if(p.status==='retrieved'){const inv=investigation(cid,sid);return !!(inv&&!supportsMastery(cid,sid,p.retrievedAt)&&(Date.now()-Date.parse(inv.completedAt))>=DAY_MS);}const anchor=p.reviewAt||p.firstTransferAt;return !!(anchor&&(Date.now()-Date.parse(anchor))>=DAY_MS);}
function promoteIfSupported(cid,sid){const id=key(cid,sid),p=db.proficiency[id];if(!p||p.status!=='retrieved'||!p.retrievedAt)return false;if((Date.now()-Date.parse(p.retrievedAt))>REVIEW_MS)return false;if(!supportsMastery(cid,sid,p.retrievedAt))return false;p.status='mastered';p.masteredAt=new Date().toISOString();p.reviewAt=null;p.reviewReason='';db.completed[id]=true;activity('Mastery supported',skill(cid,sid).title,'Delayed retrieval and a completed reasoning investigation now agree.');return true;}
function nextMove(cid,sid){const st=statusOf(cid,sid),inv=investigation(cid,sid);if(retestDue(cid,sid))return {action:'start-retest',label:'Begin delayed retrieval check'};if(st==='mastered')return {action:'start-investigation',label:'Revisit the investigation'};if(st==='not-started')return {action:'start-lesson',label:'Study this pattern'};if(!inv)return {action:'start-investigation',label:'Build the investigation'};return {action:'start-lesson',label:'Revisit the lesson while you wait'};}
function mastery(cid,sid){const a=attemptsFor(cid,sid).slice(-6);return a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):0;}
function flagTransfer(cid,sid,assisted){const id=key(cid,sid),now=new Date().toISOString(),old=db.proficiency[id];db.proficiency[id]={...(old||{}),status:['mastered','retrieved'].includes(old?.status)?old.status:'transfer',firstTransferAt:old?.firstTransferAt||now,assisted:!!assisted,masteredAt:old?.masteredAt||null,reviewAt:old?.reviewAt||null};save();}
function freshBuild(){return {fills:{},picked:null,attempts:0,results:null,done:false,firstCorrect:null,revealed:false};}
function archiveConstruction(b,result,attempt){const rows=b.rows.map((row,i)=>({label:row.label,values:Array.from({length:row.slots},(_,j)=>String(lessonBuild.fills[i]?.[j]??'')),correct:!!result.rows[i]?.correct,feedback:String(result.rows[i]?.feedback||'')}));db.constructionHistory.push({id:Date.now()+'-'+Math.random().toString(16).slice(2),courseId,skillId,attempt,correct:!!result.correct,rows,at:new Date().toISOString()});db.constructionHistory=db.constructionHistory.slice(-1000);}
