function resumeInfo(){
 if(db.activeInvestigation)return {kind:'investigation',label:`Continue ${skill(db.activeInvestigation.courseId,db.activeInvestigation.skillId).title}`};
 if(db.activeLesson)return {kind:'lesson',label:`Continue ${skill(db.activeLesson.courseId,db.activeLesson.skillId).title}`};
 if(db.activeQuiz)return {kind:'quiz',label:`Continue ${db.activeQuiz.type==='diagnostic'?'diagnostic':db.activeQuiz.type==='retest'?'mastery retest':'transfer practice'}`};
 return null;
}
function recommendations(cid){let cs=cid?[course(cid)]:allCourses();const focus=focusCourse(),recent=lastActiveCourse();let list=[];cs.forEach((c,ci)=>c.skills.forEach((s,si)=>{let acc=accuracy(c.id,s.id);let diag=db.diagnostics[c.id];let wrong=diag&&Array.isArray(diag.results)?diag.results.filter(r=>r.skillId===s.id&&!r.correct).length:0;const st=statusOf(c.id,s.id),inv=investigation(c.id,s.id);let priority=(isMastered(c.id,s.id)?0:80)+(acc===null?30:(100-acc*100))+wrong*13+(retestDue(c.id,s.id)?35:0)+(st==='retrieved'&&!inv?40:0)+(st==='transfer'&&!inv?25:0)+(!cid&&c.id===focus?45:0)+(!cid&&!focus&&c.id===recent?15:0);list.push({course:c,skill:s,priority,wrong,order:ci*100+si});}));return list.sort((a,b)=>b.priority-a.priority||a.order-b.order);}
