function evidenceCopy(html){return String(html).replaceAll('MASTERY RULE · SHOWN BEFORE TRANSFER','EVIDENCE RULE · SHOWN BEFORE FIRST TRANSFER').replaceAll('patterns verified','evidence sets complete').replaceAll('Patterns verified','Evidence sets complete').replaceAll('mastery items','delayed-retrieval items').replaceAll('mastery questions','delayed-retrieval questions').replaceAll('mastery-pool','delayed-retrieval-pool').replaceAll('mastery retest','delayed retrieval check').replaceAll('Mastery supported','Evidence set complete').replaceAll('mastery is supported','the checked evidence set is complete').replaceAll('counts toward mastery','counts as investigation evidence');}
