function navigate(v,extras={},fromHistory=false){if(extras.courseId)courseId=extras.courseId;if(extras.skillId)skillId=extras.skillId;view=v;db.lastView=v;save();if(!fromHistory&&window.history?.pushState){try{window.history.pushState({patternwork:true,view:v,courseId,skillId},'',window.location?.href||undefined);}catch(_){/* WKWebView or file:// may restrict history updates */}}render();window.scrollTo({top:0,behavior:'instant'});}
